using System;using System.Linq;using System.Text.Json;using System.IO;using MotorwaysSim;
namespace MotorwaysSim {public sealed partial class TrafficWorld {public void JumpIdleTo(double at){if(ActiveCars!=0)throw new Exception("Topology diagnostic unexpectedly has moving cars");TickCount=Math.Max(TickCount,(int)Math.Ceiling(at/Rules.TickSeconds)-1);Time=TickCount*Rules.TickSeconds;}}}
class Topology {static void Main(string[] a){var opt=new JsonSerializerOptions{IncludeFields=true,PropertyNameCaseInsensitive=true};var s=new CustomScenarioSession(JsonSerializer.Deserialize<CustomScenarioDefinition>(File.ReadAllText(a[0]),opt));var wall=System.Diagnostics.Stopwatch.StartNew();try {while(!s.Complete){if(wall.Elapsed.TotalSeconds>30)throw new Exception("30s topology-only diagnostic cap");foreach(var b in s.World.Buildings){b.Demand=0;b.DemandCountdown=1e9;}if(s.CompletedEvents<s.Definition.events.Length)s.World.JumpIdleTo(s.Definition.events[s.CompletedEvents].at);else s.World.JumpIdleTo(s.Definition.duration);s.AdvanceTick();}Console.WriteLine(JsonSerializer.Serialize(new{mode="TOPOLOGY_ONLY_IDLE_TIME_JUMPS_NO_TRAFFIC_NO_SCORE",s.CompletedEvents,total=s.Definition.events.Length,s.World.Time,s.World.Inventory},opt));}catch(Exception e){Console.WriteLine(JsonSerializer.Serialize(new{mode="TOPOLOGY_ONLY_IDLE_TIME_JUMPS_NO_TRAFFIC_NO_SCORE",error=e.Message,s.CompletedEvents,s.World.Time,s.World.Inventory,audit=s.Audit.TakeLast(12)},opt));Environment.ExitCode=1;}}}
